import math

class Statistics3:
    """
    This is a class that implements methods for calculating indicators such as median, mode, correlation matrix, and Z-score in statistics.
    """

    @staticmethod
    def median(data):
        sorted_data = sorted(data)
        n = len(sorted_data)
        if n % 2 == 1:
            return sorted_data[n // 2]
        else:
            return (sorted_data[n // 2 - 1] + sorted_data[n // 2]) / 2.0

    @staticmethod
    def mode(data):
        from collections import Counter
        counts = Counter(data)
        max_count = max(counts.values())
        return sorted([k for k, v in counts.items() if v == max_count])

    @staticmethod
    def correlation(x, y):
        n = len(x)
        mean_x = sum(x) / n
        mean_y = sum(y) / n
        numerator = sum((x[i] - mean_x) * (y[i] - mean_y) for i in range(n))
        denom_x = math.sqrt(sum((xi - mean_x) ** 2 for xi in x))
        denom_y = math.sqrt(sum((yi - mean_y) ** 2 for yi in y))
        if denom_x == 0 or denom_y == 0:
            return None
        return numerator / (denom_x * denom_y)

    @staticmethod
    def mean(data):
        if len(data) == 0:
            return None
        return sum(data) / len(data)

    @staticmethod
    def correlation_matrix(data):
        # data is a list of rows, each row has the same number of columns
        # We need to compute correlation between columns
        n_cols = len(data[0])
        # Extract columns
        cols = [[data[row][col] for row in range(len(data))] for col in range(n_cols)]
        matrix = []
        for i in range(n_cols):
            row = []
            for j in range(n_cols):
                row.append(Statistics3.correlation(cols[i], cols[j]))
            matrix.append(row)
        return matrix

    @staticmethod
    def standard_deviation(data):
        n = len(data)
        mean = sum(data) / n
        variance = sum((x - mean) ** 2 for x in data) / n
        return math.sqrt(variance)

    @staticmethod
    def z_score(data):
        std = Statistics3.standard_deviation(data)
        if std == 0:
            return None
        mean = sum(data) / len(data)
        return [(x - mean) / std for x in data]

